    serverSocket?.send(
      '[{"T": "q", "S": "AAPL", "bx": "B", "bp": 380.9, "bs": 3, "ax": "B", "ap": 381.1, "as": 5, "c": ["R"], "z": "C", "t": "2000-01-01T00:00:00Z"}]',
    )
    await expectErrorOrLastGood(good)
